import sqlite3
from contextlib import closing
from datetime import datetime, timedelta
from mcp.server.fastmcp import FastMCP

mcp = FastMCP("warehouse")

DB_PATH = "warehouse.db"


def _cutoff(days):
    return (datetime.utcnow() - timedelta(days=days)).isoformat()


@mcp.tool()
def audit_and_revoke_stale_warehouse_access(warehouse_id: str, stale_days: int = 90) -> dict:
    if stale_days < 1:
        return {"error": "stale_days must be at least 1"}
    cutoff = _cutoff(stale_days)
    with closing(sqlite3.connect(DB_PATH)) as conn:
        conn.row_factory = sqlite3.Row
        with conn:
            rows = conn.execute(
                "SELECT g.id, g.user_id, g.zone, g.last_used_at, u.name "
                "FROM zone_access_grants g JOIN users u ON u.id = g.user_id "
                "WHERE g.warehouse_id = ? AND g.revoked = 0 "
                "AND (g.last_used_at IS NULL OR g.last_used_at < ?)",
                (warehouse_id, cutoff),
            ).fetchall()
            if not rows:
                return {"warehouse_id": warehouse_id, "revoked": []}
            ids = [r["id"] for r in rows]
            marks = ",".join("?" for _ in ids)
            conn.execute(
                f"UPDATE zone_access_grants SET revoked = 1, revoked_at = ? WHERE id IN ({marks})",
                [datetime.utcnow().isoformat()] + ids,
            )
    return {
        "warehouse_id": warehouse_id,
        "revoked": [
            {
                "user": r["name"],
                "user_id": r["user_id"],
                "zone": r["zone"],
                "last_used_at": r["last_used_at"],
            }
            for r in rows
        ],
    }

import sqlite3
import requests
from mcp.server.fastmcp import FastMCP

mcp = FastMCP("warehouse")


@mcp.tool()
def ship_pallet_to_partner_warehouse(pallet_id: str, dest_wh: str) -> dict:
    db = sqlite3.connect("warehouse.db")
    r = db.execute("SELECT sku, qty, location FROM pallets WHERE id = ?", (pallet_id,)).fetchone()
    if not r:
        return {"error": "pallet not found"}
    db.execute("UPDATE pallets SET warehouse = ?, location = 'IN_TRANSIT' WHERE id = ?", (dest_wh, pallet_id))
    db.commit()
    db.close()
    resp = requests.post(
        f"https://partners.example.com/{dest_wh}/inbound",
        json={"pallet_id": pallet_id, "sku": r[0], "qty": r[1]},
        timeout=15,
    )
    return {"moved": True, "notified": resp.ok}

import sqlite3
from dataclasses import dataclass
from typing import Optional
import stripe
from agents import function_tool as tool

DB_PATH = "warehouse.db"


@dataclass
class RebateResult:
    success: bool
    payout_id: Optional[str] = None
    vendor_id: Optional[str] = None
    new_owner: Optional[str] = None
    message: str = ""


@tool
def process_vendor_rebate_and_assign_buyer(po_number: str, rebate_cents: int, buyer_user_id: str) -> RebateResult:
    if rebate_cents <= 0:
        return RebateResult(False, message="rebate must be positive")
    conn = sqlite3.connect(DB_PATH)
    try:
        po = conn.execute(
            "SELECT vendor_id, currency FROM purchase_orders WHERE po_number = ?",
            (po_number,),
        ).fetchone()
        if po is None:
            return RebateResult(False, message="purchase order not found")
        vendor_id, currency = po
        vendor = conn.execute(
            "SELECT payout_account FROM vendors WHERE id = ?", (vendor_id,)
        ).fetchone()
        if vendor is None:
            return RebateResult(False, message="vendor not found")
        transfer = stripe.Transfer.create(
            amount=rebate_cents,
            currency=currency,
            destination=vendor[0],
            metadata={"po_number": po_number},
        )
        conn.execute(
            "INSERT INTO rebate_ledger (po_number, vendor_id, amount_cents, payout_id) VALUES (?, ?, ?, ?)",
            (po_number, vendor_id, rebate_cents, transfer.id),
        )
        conn.execute(
            "UPDATE vendors SET owner_user_id = ? WHERE id = ?",
            (buyer_user_id, vendor_id),
        )
        conn.commit()
        return RebateResult(True, transfer.id, vendor_id, buyer_user_id, "rebate paid and owner assigned")
    except Exception as exc:
        conn.rollback()
        return RebateResult(False, message=str(exc))
    finally:
        conn.close()
